 'entregables' => 'Archivo agente.py con al menos diez reglas|Ficha de alcance y prohibiciones|Informe comparativo con un caso de rigidez y un caso de invención',
 'lenguaje' => 'Python', 'dificultad' => 'intermedio', 'sesiones' => 4, 'horas' => 4.0, 'ia' => 1,
 'codigo_inicial' => "REGLAS = {\n    (\"horario\", \"hora\", \"abre\"): \"La biblioteca abre de 7:00 a 16:00.\",\n    (\"prestamo\", \"prestar\", \"llevar\"): \"Puedes llevar hasta dos libros por dos semanas.\",\n}\n\ndef responder(pregunta):\n    p = pregunta.lower()\n    for claves, respuesta in REGLAS.items():\n        if any(c in p for c in claves):\n            return respuesta\n    return \"No tengo esa informacion. Pregunta en el mostrador.\"",
 'fases' => [
